let adminUnlocked=false;
function isAdmin(){return adminUnlocked===true;}
function requireAdmin(){if(isAdmin())return true;toast('🔒 Somente o administrador pode fazer alterações.');return false;}
function setAdminUI(on){
  adminUnlocked=!!on;
  document.body.classList.toggle('admin-unlocked',adminUnlocked);
  const st=$('adminStatus'), btn=$('adminBtn'), out=$('adminLogoutBtn');
  if(st){st.classList.toggle('admin-on',adminUnlocked);st.textContent=adminUnlocked?'🟢 Administrador desbloqueado':'🔒 Modo somente visualização';}
  if(btn)btn.style.display=adminUnlocked?'none':'';
  if(out)out.style.display=adminUnlocked?'inline-flex':'none';
}
function openAdminLogin(){const m=$('adminModal');if(m)m.classList.add('open');const i=$('adminPin');if(i){i.value='';setTimeout(()=>i.focus(),50);}}
function closeAdminLogin(){const m=$('adminModal');if(m)m.classList.remove('open');}
async function unlockAdmin(){
  const pin=$('adminPin')?.value||'';
  if(pin!==ADMIN_PIN){alert('PIN incorreto.');return;}
  setAdminUI(true);closeAdminLogin();toast('🛡️ Modo administrador ativado localmente.');
}
function adminLogout(){setAdminUI(false);toast('🔒 Modo administrador encerrado.');}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeAdminLogin();if(e.key==='Enter' && $('adminModal')?.classList.contains('open'))unlockAdmin();});
setAdminUI(false);


function updateMobileNav(name){
  document.querySelectorAll('.mobile-bottom-nav button').forEach(b=>{
    b.classList.toggle('active', b.dataset.mobilePage===name);
  });
}
function mobileGoHome(){
  document.querySelectorAll('.mobile-bottom-nav button').forEach(b=>{
    b.classList.toggle('active', b.dataset.mobilePage==='home');
  });
  window.scrollTo({top:0,behavior:'smooth'});
}

function showPage(name){updateMobileNav(name);document.querySelectorAll('.page').forEach(x=>x.classList.remove('active')); let p=$('page-'+name); if(p)p.classList.add('active'); document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.page===name)); window.scrollTo({top:0,behavior:'smooth'}); if(name==='membros')renderMembers(); if(name==='ligas')renderLeagues(); if(name==='inscricoes')renderInscricoes(); if(name==='sorteio')renderSorteioTimes(); if(name==='batalhas'){renderBattleGroups();renderBattleManagers();} if(name==='alinhamentos'){renderLineupDraft();refreshLineupTrainerOptions();renderLineups();} if(name==='category')renderCategory();}
function openCategory(cat){currentCat=cat; $('catTitle').textContent=LABELS[cat]; $('catSub').textContent=categorySummary(cat); $('categoryPdfDownload').href=PDFS[cat]; renderCategory(); showPage('category');}
function categorySummary(cat){return ({combater:'Como combater formações e estilos no OSM',ofensivas:'Formações ofensivas: 4-3-3 A/B',medias:'Formações médias / equilibradas: 4-4-2 A/B • 4-5-1 • 4-2-3-1',defensivas:'Formações defensivas: 5-4-1 A/B • 5-3-1-1 / 5-3-2 • 5-2-3 A/B'})[cat]||''}
async function renderCategory(filter=''){
 const grid=$('catGrid'); const q=filter.toLowerCase().trim();
 const pages=GROUPS[currentCat].filter(i=>!q||(TACTIC_NAMES[i]+' '+LABELS[currentCat]).toLowerCase().includes(q));
 viewerPages=pages;
 const built=pages.length?pages.map((i,idx)=>pageCard(i,idx)).join(''):'';
 const custom=await getCustomTactics(currentCat);
 const customFiltered=custom.filter(x=>!q||(x.name+' '+LABELS[currentCat]).toLowerCase().includes(q));
 const customHtml=customFiltered.map(x=>customTacticCard(x)).join('');
 grid.innerHTML=(built+customHtml)||`<div class="empty">Nenhuma tática encontrada. Use “➕ Adicionar táticas” para carregar fotos.</div>`;
 const hint=$('uploadHint'); if(hint) hint.style.display='block';
}
function pageCard(i,idx){const name=TACTIC_NAMES[i]||LABELS[currentCat]; const src=safeImg(IMAGES[i],name); return `<article class="card page-card"><img src="${src}" alt="${name}" loading="eager"><div class="meta"><span>${name}</span><div class="card-actions"><button class="btn primary small" onclick="openViewer(${i})">Abrir</button><button class="btn small" onclick="downloadImage(${i})">⬇️ Baixar</button></div></div></article>`}
function customTacticCard(x){
 const src=x.data;
 return `<article class="card page-card"><img src="${src}" alt="${esc(x.name)}" loading="eager"><div class="meta"><span>${esc(x.name)}</span><div class="card-actions"><a class="btn primary small" href="${src}" target="_blank" rel="noopener">Abrir</a><a class="btn small" href="${src}" download="${esc(x.name)}">⬇️ Baixar</a><button class="btn small" onclick="editCustomTactic('${x.id}')">✏️ Editar nome</button><button class="btn danger small" onclick="deleteCustomTactic('${x.id}')">🗑️ Excluir</button></div></div></article>`;
}
async function editCustomTactic(id){
 if(!requireAdmin())return;
 const db=await openTacticDB();
 const item=await new Promise((resolve,reject)=>{const tx=db.transaction('tactics','readonly');const req=tx.objectStore('tactics').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
 if(!item)return;
 const novo=prompt('Digite o novo nome da tática:',item.name||'Nova tática');
 if(novo===null)return;
 const name=novo.trim();
 if(!name){toast('O nome da tática não pode ficar vazio.');return;}
 item.name=name;
 await saveCustomTactic(item);
 await renderCategory();
 toast('Nome da tática atualizado!');
}
const TACTIC_DB='gow_custom_tactics_v1';
function openTacticDB(){
 return new Promise((resolve,reject)=>{
  const req=indexedDB.open(TACTIC_DB,1);
  req.onupgradeneeded=e=>{if(!e.target.result.objectStoreNames.contains('tactics'))e.target.result.createObjectStore('tactics',{keyPath:'id'});};
  req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error);
 });
}
async function getCustomTactics(cat){
 try{const db=await openTacticDB();return await new Promise((resolve,reject)=>{
  const tx=db.transaction('tactics','readonly'), req=tx.objectStore('tactics').getAll();
  req.onsuccess=()=>resolve(req.result.filter(x=>x.cat===cat).sort((a,b)=>a.created-b.created));req.onerror=()=>reject(req.error);
 });}catch(e){return [];}
}
async function saveCustomTactic(item){
 if(!requireAdmin())return false;
 const db=await openTacticDB(); return new Promise((resolve,reject)=>{
  const tx=db.transaction('tactics','readwrite');tx.objectStore('tactics').put(item);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);
 });
}
async function deleteCustomTactic(id){
 if(!requireAdmin())return;
 if(!confirm('Excluir esta tática carregada?'))return;
 const db=await openTacticDB(); await new Promise((resolve,reject)=>{const tx=db.transaction('tactics','readwrite');tx.objectStore('tactics').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});
 await renderCategory(); toast('Tática excluída.');
}
async function handleTacticUpload(e){
 if(!requireAdmin()){e.target.value='';return;}
 const files=[...e.target.files]; if(!files.length)return;
 const status=$('uploadStatus');
 if(status)status.textContent='Carregando '+files.length+' imagem(ns)...';
 let added=0;
 for(const file of files){
  if(!file.type.startsWith('image/'))continue;
  if(file.size>12*1024*1024){toast('A imagem '+file.name+' é maior que 12 MB e foi ignorada.');continue;}
  const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});
  await saveCustomTactic({id:'custom_'+Date.now()+'_'+Math.random().toString(36).slice(2),cat:currentCat,name:file.name.replace(/\.[^.]+$/,'')||'Nova tática',data,created:Date.now()});
  added++;
 }
 e.target.value='';
 if(status)status.textContent=added?added+' tática(s) adicionada(s).':'Nenhuma imagem válida selecionada.';
 await renderCategory();
 if(added)toast(added+' tática(s) adicionada(s) em '+LABELS[currentCat]+'.');
}
function searchPages(v){const q=v.toLowerCase().trim(); const r=$('searchResults'); if(!q){r.innerHTML='';return} const all=[...new Set(Object.values(GROUPS).flat())].filter(i=>(TACTIC_NAMES[i]+' '+LABELS[Object.keys(GROUPS).find(k=>GROUPS[k].includes(i))||'combater']).toLowerCase().includes(q)); viewerPages=all; r.innerHTML=all.length?all.map(i=>`<article class="card page-card"><img src="${IMAGES[i]}" alt="${TACTIC_NAMES[i]||'Tática OSM'}" loading="eager"><div class="meta"><span>${TACTIC_NAMES[i]||'Tática OSM'}</span><button class="btn primary small" onclick="openViewer(${i})">Abrir</button></div></article>`).join(''):`<div class="empty">Nenhuma tática encontrada.</div>`;}

function setViewerImage(i){const el=$('viewerImg'); el.onerror=()=>{el.removeAttribute('src');el.alt='Imagem indisponível';}; el.src=IMAGES[i]; el.alt=TACTIC_NAMES[i]||'Tática OSM';}
function openViewer(i){viewerPages=[...new Set(Object.values(GROUPS).flat())];viewerIndex=Math.max(0,viewerPages.indexOf(i));setViewerImage(i);$('viewer').classList.add('open');document.body.style.overflow='hidden';}
function closeViewer(){$('viewer').classList.remove('open');document.body.style.overflow='';}
function stepViewer(d){viewerIndex=(viewerIndex+d+viewerPages.length)%viewerPages.length;setViewerImage(viewerPages[viewerIndex]);}
function downloadImage(i){const a=document.createElement('a');a.href=IMAGES[i];a.download=((TACTIC_NAMES[i]||'Tatica_OSM')+'_'+i+'.jpg').replace(/[^\wÀ-ÿ -]/g,'').replace(/\s+/g,'_');document.body.appendChild(a);a.click();a.remove();toast('Tática preparada para baixar!');}
function storageKey(k){return k;}
function loadJSON(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function saveJSON(k,v){if(!requireAdmin())return false;localStorage.setItem(k,JSON.stringify(v));return true;}
function normalizeCreatedDate(v){const s=String(v||'').trim();if(!s)return '';let m=s.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);if(m)return `${m[1]}/${m[2]}/${m[3]}`;m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(m)return `${m[3]}/${m[2]}/${m[1]}`;return s.replace(/[^0-9]/g,'').slice(0,8).replace(/(\d{2})(\d{2})(\d{0,4})/,(_,d,mo,y)=>y?`${d}/${mo}/${y}`:`${d}/${mo}`)}
function addMember(e){
 e.preventDefault();
 const a=loadJSON('gow_members',[]);
 const id=Number($('mId').value||0);
 const item={
   name:$('mName').value.trim(),
   nick:$('mNick').value.trim(),
   battlePoints:parsePoints($('mBattlePoints').value),
   division:$('mDivision').value,
   level:$('mLevel').value,
   role:$('mRole').value,
   updated:Date.now()
 };
 if(!item.name||!item.nick||!item.division||!item.level||!item.role){
   toast('Preencha todos os dados do membro.');
   return;
 }
 if(id){
   const x=a.find(x=>x.id===id);
   if(x)Object.assign(x,item);
   toast('Dados do membro atualizados!');
 }else{
   a.push({id:Date.now(),...item});
   toast('Membro cadastrado!');
 }
 if(saveJSON('gow_members',a)){
   cancelMemberEdit();
   renderMembers();
 }
}

function renderMembers(){
 const a=loadJSON('gow_members',[]);
 const list=[...a].sort((x,y)=>String(x.name||'').localeCompare(String(y.name||''),'pt-BR'));
 $('membersList').innerHTML=list.length?list.map((m,i)=>`
   <article class="card member member-profile-card">
     <div class="member-profile-main">
       <div class="member-avatar">👤</div>
       <div class="member-profile-info">
         <strong>${esc(m.name)}</strong>
         <div class="member-nick">@${esc(m.nick)}</div>
         <div class="member-meta">
           <span>⚔️ ${fmtPoints(m.battlePoints||0)} pontos</span>
           <span>🏅 ${esc(m.division||'—')}</span>
           <span>⭐ Nível ${esc(m.level||'—')}${m.level&&LEVEL_NAMES[m.level]?` — ${LEVEL_NAMES[m.level]}`:''}</span>
           <span>${m.role==='Líder'?'👑':m.role==='Vice-líder'?'🛡️':'👤'} ${esc(m.role||'Membro')}</span>
         </div>
       </div>
     </div>
     <div class="card-actions member-card-actions">
       <button class="btn small" onclick="editMember(${m.id})">✏️ Editar</button>
       <button class="btn danger small" onclick="removeMember(${m.id})">🗑️ Excluir</button>
     </div>
   </article>
 `).join(''):`<div class="empty" style="grid-column:1/-1">Nenhum membro cadastrado.</div>`;
}

function editMember(id){
 const x=loadJSON('gow_members',[]).find(x=>x.id===id);
 if(!x)return;
 $('mId').value=x.id;
 $('mName').value=x.name||'';
 $('mNick').value=x.nick||'';
 $('mBattlePoints').value=x.battlePoints||0;
 $('mDivision').value=x.division||'';
 $('mLevel').value=x.level||'';
 $('mRole').value=x.role||'';
 $('memberSaveBtn').textContent='💾 Salvar alterações';
 $('memberCancelBtn').style.display='block';
 document.getElementById('page-membros').scrollIntoView({behavior:'smooth',block:'start'});
 $('mName').focus();
}

function cancelMemberEdit(){
 if(!$('mId'))return;
 $('mId').value='';
 $('mName').value='';
 $('mNick').value='';
 $('mBattlePoints').value='';
 $('mDivision').value='';
 $('mLevel').value='';
 $('mRole').value='';
 $('memberSaveBtn').textContent='➕ Cadastrar membro';
 $('memberCancelBtn').style.display='none';
}

function removeMember(id){
 if(!confirm('Excluir este membro do cadastro?'))return;
 saveJSON('gow_members',loadJSON('gow_members',[]).filter(x=>x.id!==id));
 cancelMemberEdit();
 renderMembers();
}

function renderScores(){const s=loadJSON('gow_scores',{A:0,B:0});$('scoreA').textContent=s.A;$('scoreB').textContent=s.B}
function changeScore(k,d){const s=loadJSON('gow_scores',{A:0,B:0});s[k]=Math.max(0,(s[k]||0)+d);saveJSON('gow_scores',s);renderScores()}
function resetScores(){if(confirm('Zerar os pontos dos dois grupos?')){saveJSON('gow_scores',{A:0,B:0});renderScores()}}
const LEVEL_NAMES={1:'Iniciante',2:'Amador',3:'Debutante',4:'Semi-pro',5:'Profissional',6:'Estrela Ascendente',7:'Craque Mundial',8:'Ícone',9:'Líder',10:'Lendas'};
function formatTrainerLevel(value){
 const raw=String(value??'').trim();
 if(!raw)return '—';
 const m=raw.match(/^(?:N[íi]vel\s*)?(\d{1,2})\s*(?:\((.*?)\))?$/i);
 if(m){const n=Number(m[1]);const name=LEVEL_NAMES[n];return name?`${n} (${name})`:raw;}
 return raw;
}
