function getHistory(){
 const extra=loadJSON('gow_champions_ligas',[]);
 const edits=loadJSON('gow_champion_edits',{});
 const deleted=loadJSON('gow_champion_deleted',{});
 const base=HISTORY.map((x,i)=>deleted[i]?null:{...(edits[i]?{...x,...edits[i]}:x),_historyIndex:i,_builtin:true}).filter(Boolean);
 return [...base,...extra.map(x=>({...x,_builtin:false}))];
}
function toggleChampionForm(force){
 const wrap=$('championFormWrap'); if(!wrap)return;
 const open=typeof force==='boolean'?force:wrap.style.display==='none'; wrap.style.display=open?'block':'none';
 if(!open){wrap.dataset.editIndex='';$('hcId').value='';$('hcCategory').value='';$('hcLeague').value='';$('hcChampion').value='';$('hcGroup').value='THE GHOSTS OF SPARTA';}
 else {$('hcLeague').focus();}
}
function addLeagueChampion(e){
 e.preventDefault(); const category=$('hcCategory').value, league=$('hcLeague').value.trim(), champion=$('hcChampion').value.trim(), group=$('hcGroup').value;
 if(!category||!league||!champion){toast('Preencha todos os dados do campeão.');return;}
 const wrap=$('championFormWrap'), editIndex=wrap.dataset.editIndex;
 if(editIndex!==undefined && editIndex!==''){
   const idx=Number(editIndex), history=getHistory(), current=history[idx];
   if(!current){toast('Registro não encontrado.');return;}
   if(current._builtin){const edits=loadJSON('gow_champion_edits',{}); edits[current._historyIndex]={cat:category,name:league,champion,group}; saveJSON('gow_champion_edits',edits); const deleted=loadJSON('gow_champion_deleted',{}); delete deleted[current._historyIndex]; saveJSON('gow_champion_deleted',deleted);}
   else {const extra=loadJSON('gow_champions_ligas',[]), pos=extra.findIndex(x=>x.id===current.id); if(pos>=0){Object.assign(extra[pos],{cat:category,name:league,champion,group});saveJSON('gow_champions_ligas',extra);}}
   toast('Todos os dados do campeão foram atualizados!');
 }else{
   const extra=loadJSON('gow_champions_ligas',[]); extra.push({id:Date.now(),cat:category,name:league,champion,group}); saveJSON('gow_champions_ligas',extra); toast('Novo campeão adicionado!');
 }
 e.target.reset(); $('hcGroup').value='THE GHOSTS OF SPARTA'; toggleChampionForm(false); renderLeagues();
}
function editLeagueChampion(index){
 const history=getHistory(), x=history[index]; if(!x)return;
 $('hcCategory').value=x.cat==='Batalha amistosa'?'Torneio':x.cat; $('hcLeague').value=x.name||''; $('hcChampion').value=x.champion||''; $('hcGroup').value=x.group||'THE GHOSTS OF SPARTA';
 $('championFormWrap').style.display='block'; $('championFormWrap').dataset.editIndex=String(index); $('hcLeague').focus();
}
function removeLeagueChampion(index){
 const history=getHistory(), x=history[index]; if(!x)return;
 if(!confirm('Excluir este registro do ranking?'))return;
 if(x._builtin){const deleted=loadJSON('gow_champion_deleted',{}); deleted[x._historyIndex]=true; saveJSON('gow_champion_deleted',deleted);}
 else {saveJSON('gow_champions_ligas',loadJSON('gow_champions_ligas',[]).filter(y=>y.id!==x.id));}
 renderLeagues(); toast('Registro removido do ranking.');
}
function renderLeagues(){
 const history=getHistory();
 const count=cat=>{const m={};history.filter(x=>x.cat===cat).forEach(x=>m[x.champion]=(m[x.champion]||0)+1);return Object.entries(m).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));};
 const league=count('Liga'),cup=count('Copa'),tour=count('Torneio');
 const all={}; [...league,...cup,...tour].forEach(([n,v])=>all[n]=(all[n]||0)+v); const overall=Object.entries(all).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));
 const card=(x,i)=>{
  const pos=i+1;
  const medal=pos===1?'🥇':pos===2?'🥈':pos===3?'🥉':'🏅';
  const cls=pos<=3?`top-${pos}`:'standard';
  return `<article class="card gow-ranking-card ${cls}">
    <div class="gow-rank-badge">${medal}<span>${pos}º</span></div>
    <div class="gow-rank-info">
      <strong>${esc(x[0])}</strong>
      <div class="muted">${x[1]} ${x[1]===1?'título':'títulos'}</div>
    </div>
    <div class="gow-rank-value">${x[1]}</div>
  </article>`;
};
 $('titlesRanking').innerHTML=overall.map(card).join(''); $('leagueRanking').innerHTML=league.map(card).join(''); $('cupRanking').innerHTML=cup.map(card).join(''); $('tournamentRanking').innerHTML=tour.map(card).join('');
 $('leagueHistory').innerHTML=history.map((x,i)=>{
   const isExtra=i>=HISTORY.length;
   return `<article class="card"><div><strong>${esc(x.name)}</strong><div class="muted">${esc(x.cat)} • Campeão: <b>${esc(x.champion)}</b>${x.group?` • ${esc(x.group)}`:''}</div></div><div class="card-actions"><button class="btn small" type="button" onclick="editLeagueChampion(${i})">✏️ Atualizar</button><button class="btn danger small" type="button" onclick="removeLeagueChampion(${i})">Excluir</button></div></article>`;
 }).join('');
}
let currentLineupId='';
let lineupDraft=[];
function lineupKey(id){return 'gow_lineup_'+id}
function normalizeLineupGroup(x){
  const g=String(x?.group||'').trim();
  if(g==='THE GHOSTS OF SPARTA B') return g;
  if(g==='THE GHOSTS OF SPARTA') return g;
  const groups=(x?.players||[]).map(p=>p.group).filter(Boolean);
  if(groups.length && groups.every(v=>v==='THE GHOSTS OF SPARTA B')) return 'THE GHOSTS OF SPARTA B';
  return 'THE GHOSTS OF SPARTA';
}
function setLineupGroup(group){
  const g=group==='THE GHOSTS OF SPARTA B'?'THE GHOSTS OF SPARTA B':'THE GHOSTS OF SPARTA';
  $('luGroup').value=g;
  $('lpGroup').value=g;
  refreshLineupTrainerOptions();
  renderLineupDraft();
}
function getLineupTrainerRecord(key,group){
  const g=group||$('luGroup')?.value||'THE GHOSTS OF SPARTA';
  const managers=loadJSON('gow_battle_managers',[]);
  const members=loadJSON('gow_members',[]);
  // O cadastro de Pontos de batalhas é a fonte principal, pois contém nível + pontos.
  const manager=managers.find(m=>(m.nick||'')===key && (m.group||'THE GHOSTS OF SPARTA')===g);
  if(manager) return {trainer:manager.nick||key,level:String(manager.level||'').split(' ')[0],points:Number(manager.points)||0,group:g};
  const member=members.find(m=>(m.nick||m.name||'')===key && (m.group||'THE GHOSTS OF SPARTA')===g);
  if(member) return {trainer:member.name||member.nick||key,level:String(member.level||'').split(' ')[0],points:Number(member.points)||0,group:g};
  return null;
}
function refreshLineupTrainerOptions(){
  const sel=$('lpTrainer');if(!sel)return;
  const group=$('luGroup')?.value||'THE GHOSTS OF SPARTA';
  const managers=loadJSON('gow_battle_managers',[]);
  const members=loadJSON('gow_members',[]);
  const map=new Map();
  managers.filter(m=>(m.group||'THE GHOSTS OF SPARTA')===group).forEach(m=>{
    const key=m.nick||''; if(key) map.set(key,{key,name:m.nick,group,level:String(m.level||'').split(' ')[0],points:Number(m.points)||0});
  });
  members.filter(m=>(m.group||'THE GHOSTS OF SPARTA')===group).forEach(m=>{
    const key=m.nick||m.name||''; if(key && !map.has(key)) map.set(key,{key,name:m.name||m.nick,group,level:String(m.level||'').split(' ')[0],points:Number(m.points)||0});
  });
  sel.innerHTML='<option value="">Escolha o treinador</option>'+Array.from(map.values()).map(x=>`<option value="${esc(x.key)}" data-group="${esc(x.group)}" data-level="${esc(x.level||'')}" data-points="${esc(x.points||0)}">${esc(x.name)}</option>`).join('');
  $('lpGroup').value=group;
  updateLineupTrainerInfo();
}
function updateLineupTrainerInfo(){
  const sel=$('lpTrainer'); if(!sel)return;
  const info=$('lpTrainerInfo'), nameEl=$('lpTrainerInfoName'), dataEl=$('lpTrainerInfoData');
  const o=sel.selectedOptions[0];
  const group=$('luGroup')?.value||'THE GHOSTS OF SPARTA';
  $('lpGroup').value=group;
  if(!o || !o.value){ if(info)info.style.display='none'; $('lpLevel').value=''; $('lpPoints').value=''; return; }
  const level=o.dataset.level||'';
  const points=Number(o.dataset.points||0);
  $('lpLevel').value=level;
  $('lpPoints').value=String(points);
  if(info){
    info.style.display='block';
    nameEl.textContent=o.textContent;
    dataEl.textContent=`Nível ${formatTrainerLevel(level)} • ${fmtPoints(points)} pontos de batalha • ${group}`;
  }
}
function addLineupPlayer(e){
  e.preventDefault();
  const trainer=$('lpTrainer').value;
  const group=$('luGroup')?.value||'THE GHOSTS OF SPARTA';
  if(!trainer){toast('Escolha um treinador.');return;}
  const record=getLineupTrainerRecord(trainer,group);
  if(!record){toast('Não foi possível encontrar os dados cadastrados deste treinador no grupo.');return;}
  const exists=lineupDraft.some(x=>x.trainer===record.trainer && x.group===group);
  if(exists){toast('Este treinador já está no alinhamento.');return;}
  if(!record.level || !record.points){toast('O treinador está cadastrado, mas ainda não possui nível e pontos de batalha completos no grupo.');return;}
  if(lineupDraft.length>=5){toast('Cada alinhamento contém exatamente 5 treinadores.');return;}
  lineupDraft.push(record);
  renderLineupDraft();
  e.target.reset();
  $('lpGroup').value=group;
  updateLineupTrainerInfo();
}
function removeLineupPlayer(i){lineupDraft.splice(i,1);renderLineupDraft();}
function renderLineupDraft(){const el=$('lineupDraft');if(!el)return;el.innerHTML=lineupDraft.length?lineupDraft.map((x,i)=>`<article class="card"><div><strong>${i+1} — ${esc(x.trainer)}</strong><div class="muted">Nível ${esc(x.level)} • ${fmtPoints(x.points)} pontos • ${esc(x.group)}</div></div><button class="btn danger small" onclick="removeLineupPlayer(${i})">Excluir</button></article>`).join(''):'<div class="empty">Nenhum treinador adicionado.</div>';updateCloseLineupButton(); }
function getGroupLineups(group){
  return loadJSON('gow_battle_lineups',[]).filter(x=>normalizeLineupGroup(x)===group);
}
function nextLineupNumber(group){
  const nums=getGroupLineups(group).map(x=>Number(x.number)||0).filter(Boolean);
  for(let i=1;i<=4;i++) if(!nums.includes(i)) return i;
  return 0;
}
function updateCloseLineupButton(){
  const btn=$('closeLineupBtn');if(!btn)return;
  const n=lineupDraft.length; const group=$('luGroup')?.value||'THE GHOSTS OF SPARTA';
  const editing=!!currentLineupId;
  const used=getGroupLineups(group).length;
  btn.disabled=n!==5 || (!editing && used>=4);
  btn.textContent=n===5?'✅ Fechar alinhamento (5/5)':`✅ Fechar alinhamento (${n}/5)`;
  if(!editing && used>=4 && n<5) btn.title='Este grupo já possui os 4 alinhamentos permitidos.';
  else btn.title='O alinhamento será salvo automaticamente ao fechar.';
}
function closeLineup(){
  const group=$('luGroup')?.value||'THE GHOSTS OF SPARTA';
  if(lineupDraft.length!==5){toast('O alinhamento precisa ter exatamente 5 treinadores.');return;}
  if(lineupDraft.some(p=>p.group!==group)){toast('Não é possível misturar treinadores dos dois grupos.');return;}
  const all=loadJSON('gow_battle_lineups',[]);
  let item;
  if(currentLineupId){
    const idx=all.findIndex(x=>String(x.id)===String(currentLineupId));
    if(idx<0){currentLineupId='';return closeLineup();}
    item={...all[idx],group,players:[...lineupDraft],updated:Date.now(),name:all[idx].name||`Alinhamento ${String(all[idx].number||1).padStart(2,'0')}`,date:new Date().toLocaleDateString('pt-BR')};
    all[idx]=item;
  }else{
    const number=nextLineupNumber(group);
    if(!number){toast('Este grupo já possui os 4 alinhamentos.');return;}
    const id=`${group==='THE GHOSTS OF SPARTA B'?'B':'A'}-${number}-${Date.now()}`;
    item={id,number,name:`Alinhamento ${String(number).padStart(2,'0')}`,date:new Date().toLocaleDateString('pt-BR'),group,players:[...lineupDraft],updated:Date.now()};
    all.push(item);currentLineupId=String(id);
  }
  saveJSON('gow_battle_lineups',all);
  renderLineups();
  toast(`${item.name} salvo automaticamente!`);
  lineupDraft=[];currentLineupId='';
  $('luId').value='';$('luName').value='';$('luDate').value='';
  renderLineupDraft();refreshLineupTrainerOptions();updateCloseLineupButton();
}
function newLineup(group='THE GHOSTS OF SPARTA'){
  const g=group==='THE GHOSTS OF SPARTA B'?'THE GHOSTS OF SPARTA B':'THE GHOSTS OF SPARTA';
  if(getGroupLineups(g).length>=4){toast('Este grupo já possui os 4 alinhamentos.');return;}
  currentLineupId='';lineupDraft=[];$('luId').value='';$('luName').value='';$('luDate').value='';$('luGroup').value=g;setLineupGroup(g);renderLineupDraft();updateCloseLineupButton();toast('Novo alinhamento iniciado: '+g+'. Selecione 5 treinadores.');
}
function editLineup(id){const x=loadJSON('gow_battle_lineups',[]).find(x=>String(x.id)===String(id));if(!x)return;const group=normalizeLineupGroup(x);currentLineupId=String(id);$('luId').value=x.id;$('luName').value=x.name||'';$('luDate').value=x.date||'';$('luGroup').value=group;lineupDraft=(x.players||[]).filter(p=>(p.group||group)===group).map(p=>({...p,group}));setLineupGroup(group);renderLineupDraft();updateCloseLineupButton();document.getElementById('page-alinhamentos').scrollIntoView({behavior:'smooth'});toast('Alinhamento aberto para edição. Feche novamente para salvar automaticamente.');}
function deleteLineup(id){if(!confirm('Excluir este alinhamento?'))return;saveJSON('gow_battle_lineups',loadJSON('gow_battle_lineups',[]).filter(x=>String(x.id)!==String(id)));if(String(currentLineupId)===String(id)){newLineup($('luGroup')?.value||'THE GHOSTS OF SPARTA');}renderLineups();toast('Alinhamento excluído.');}
function selectLineup(id){const x=loadJSON('gow_battle_lineups',[]).find(x=>String(x.id)===String(id));if(!x)return;const group=normalizeLineupGroup(x);currentLineupId=String(id);lineupDraft=(x.players||[]).filter(p=>(p.group||group)===group).map(p=>({...p,group}));$('luId').value=x.id;$('luName').value=x.name||'';$('luDate').value=x.date||'';$('luGroup').value=group;setLineupGroup(group);renderLineupDraft();updateCloseLineupButton();toast('Alinhamento selecionado: '+group+'.');}
function lineupCard(x){const num=String(x.number||0);const title=num?`Alinhamento ${num.padStart(2,'0')}`:(x.name||'Alinhamento');return `<article class="card"><div><strong>${esc(title)}</strong><div class="muted">${esc(x.group||'')} • ${(x.players||[]).length}/5 treinadores${x.date?` • ${esc(x.date)}`:''}</div></div><div class="card-actions"><button class="btn small" onclick="selectLineup('${String(x.id)}')">📋 Abrir</button><button class="btn small" onclick="editLineup('${String(x.id)}')">✏️ Editar</button><button class="btn small" onclick="viewLineupPDF('${String(x.id)}')">👁️ Visualizar PDF</button><button class="btn small" onclick="shareLineupPDF('${String(x.id)}')">📤 Compartilhar PDF</button><button class="btn primary small" onclick="downloadLineupPDF('${String(x.id)}')">⬇️ Baixar PDF</button><button class="btn danger small" onclick="deleteLineup('${String(x.id)}')">🗑️ Excluir</button></div></article>`;}
function renderLineups(){
  const all=loadJSON('gow_battle_lineups',[]);
  const a=all.filter(x=>normalizeLineupGroup(x)==='THE GHOSTS OF SPARTA').sort((x,y)=>(x.number||99)-(y.number||99));
  const b=all.filter(x=>normalizeLineupGroup(x)==='THE GHOSTS OF SPARTA B').sort((x,y)=>(x.number||99)-(y.number||99));
  const elA=$('lineupsListA'),elB=$('lineupsListB');
  if(elA)elA.innerHTML=a.length?a.map(lineupCard).join(''):'<div class="empty">Nenhum alinhamento criado para este grupo.</div>';
  if(elB)elB.innerHTML=b.length?b.map(lineupCard).join(''):'<div class="empty">Nenhum alinhamento criado para este grupo.</div>';
}
function clearLineupDraft(){if(!lineupDraft.length)return;if(!confirm('Limpar todos os treinadores deste alinhamento?'))return;lineupDraft=[];currentLineupId='';renderLineupDraft();updateCloseLineupButton();toast('Alinhamento atual limpo.');}
function getCurrentLineup(){const group=$('luGroup')?.value||'THE GHOSTS OF SPARTA';return {id:currentLineupId||'temp',name:$('luName')?.value.trim()||'Alinhamento de batalha',date:$('luDate')?.value.trim()||new Date().toLocaleDateString('pt-BR'),group,players:lineupDraft.filter(p=>p.group===group)};}
const SPARTA_CLEAN_LINEUP_TEMPLATE_A = "data:image/jpeg;base64,";
const SPARTA_CLEAN_LINEUP_TEMPLATE_B = "data:image/jpeg;base64,";
function buildLineupPDF(x){
 const blue=normalizeLineupGroup(x)==='THE GHOSTS OF SPARTA B';
 const group=blue?'THE GHOSTS OF SPARTA B':'THE GHOSTS OF SPARTA';
 const info=loadJSON('gow_battle_groups',[]).find(g=>String(g.name||'').toUpperCase()===group)||{};
 const players=(x.players||[]).slice(0,5);
 const number=Number(x.number)||Number((String(x.name||'').match(/\d+/)||[])[0])||1;
 const date=x.date||new Date(x.updated||Date.now()).toLocaleDateString('pt-BR');
 const accent=blue?'0.02 0.34 0.90':'0.85 0.03 0.09';
 const lines=[];
 const text=(px,py,size,t,b=false,color='0.03 0.10 0.22')=>lines.push(`${color} rg BT /F${b?2:1} ${size} Tf 1 0 0 1 ${px} ${py} Tm (${pdfSafeText(t)}) Tj ET`);
 // All positions are in PDF points, matched to the clean background artwork.
 text(96,604,13,String(info.division||'Divisao nao informada').slice(0,30),true);
 text(383,604,16,fmtPoints(info.points||0),true);
 text(103,548,23,`ALINHAMENTO ${String(number).padStart(2,'0')}`,true,'1 1 1');
 text(103,524,10,`${group} - ${date}`,true,'1 1 1');
 const ys=[402,335,268,201,134];
 players.forEach((p,i)=>{
  const name=String(p.trainer||'-').replace(/[ΩΩ]/g,'Omega').replace(/[º°]/g,'o').replace(/[–—]/g,'-');const level=String(formatTrainerLevel(p.level));
  text(43,ys[i],14,`${i+1}.`,true,accent);
  text(105,ys[i],name.length>25?9:11,name.slice(0,36),true);
  text(295,ys[i],level.length>21?9:11,level.slice(0,27));
  text(502,ys[i],12,fmtPoints(p.points),true);
 });
 return makeSimplePDF([{imageBehind:true,content:lines.join('\n'),images:[{name:'LineupBg',dataUrl:blue?SPARTA_CLEAN_LINEUP_TEMPLATE_B:SPARTA_CLEAN_LINEUP_TEMPLATE_A,x:0,y:0,w:595,h:842,pixelWidth:768,pixelHeight:1024}]}]);
}
function lineupPDFFile(x){const blob=buildLineupPDF(x);const n=(x.number?String(x.number).padStart(2,'0'):'00');return new File([blob],`Alinhamento_${n}_${x.group==='THE GHOSTS OF SPARTA B'?'Sparta_B':'Sparta'}.pdf`,{type:'application/pdf'});}
function getSavedLineup(id){const x=loadJSON('gow_battle_lineups',[]).find(x=>String(x.id)===String(id));if(!x)return null;const group=normalizeLineupGroup(x);return {...x,group,players:(x.players||[]).filter(p=>(p.group||group)===group)};}
function viewLineupPDF(id){const x=getSavedLineup(id);if(!x)return;const file=lineupPDFFile(x);const url=URL.createObjectURL(file);const w=window.open(url,'_blank');if(!w){toast('Permita a abertura de novas abas para visualizar o PDF.');}else setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function shareLineupPDF(id){const x=getSavedLineup(id);if(!x)return;const file=lineupPDFFile(x);try{if(navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({title:file.name,text:x.name||'Alinhamento',files:[file]});return;}if(navigator.share){await navigator.share({title:file.name,text:x.name||'Alinhamento'});return;}viewLineupPDF(id);toast('O compartilhamento de arquivos não é suportado neste navegador.');}catch(e){if(e?.name!=='AbortError')toast('Não foi possível compartilhar o PDF.');}}
function printCurrentLineupPDF(){const x=getCurrentLineup();if(x.players.length!==5){toast('Feche o alinhamento com exatamente 5 treinadores.');return;}const blob=buildLineupPDF(x);const url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000);}
function printLineupPDF(id){viewLineupPDF(id);}
function downloadCurrentLineupPDF(){const x=getCurrentLineup();if(x.players.length!==5){toast('Feche o alinhamento com exatamente 5 treinadores.');return;}downloadFile(lineupPDFFile(x));}
function downloadLineupPDF(id){const x=getSavedLineup(id);if(!x)return;downloadFile(lineupPDFFile(x));}

function parsePoints(v){
  let s=String(v??'').trim().replace(/\s/g,'');
  if(!s) return 0;
  // Accept 21133, 21.133, 21,133, 21.133,50 and 21,133.50
  if(s.includes('.') && s.includes(',')){
    const lastDot=s.lastIndexOf('.'), lastComma=s.lastIndexOf(',');
    const dec=lastComma>lastDot?',':'.';
    const thou=dec===','?/\./g:/,/g;
    s=s.replace(thou,'').replace(dec,'.');
  } else if(s.includes(',') || s.includes('.')){
    const sep=s.includes(',')?',':'.';
    const parts=s.split(sep);
    if(parts.length===2 && parts[1].length<=2) s=parts[0]+'.'+parts[1];
    else s=s.replace(sep,'');
  }
  const n=Number(s.replace(/[^0-9.-]/g,''));
  return Number.isFinite(n)?Math.max(0,Math.round(n)):0;
}
function fmtPoints(v){return Number(v||0).toLocaleString('pt-BR');}
function addBattleGroup(e){
 e.preventDefault(); const a=loadJSON('gow_battle_groups',[]); const id=Number($('bgId').value||0);
 const item={name:$('bgName').value.trim(),division:$('bgDivision').value,points:parsePoints($('bgPoints').value),updated:Date.now()};
 if(!item.name||!item.division){toast('Preencha todos os dados do grupo.');return;}
 if(id){const x=a.find(x=>x.id===id); if(x)Object.assign(x,item); toast('Todos os dados do grupo foram atualizados!');}
 else {a.push({id:Date.now(),...item});toast('Grupo cadastrado!');}
 saveJSON('gow_battle_groups',a);e.target.reset();$('bgId').value='';renderBattleGroups();
}
function renderBattleGroups(){
  const a=loadJSON('gow_battle_groups',[]).sort((x,y)=>y.points-x.points);
  const medal=i=>i===0?'🥇':i===1?'🥈':i===2?'🥉':'🏅';
  const cls=i=>i<3?`battle-top-${i+1}`:'battle-standard';
  $('battleGroupsList').innerHTML=a.length?a.map((x,i)=>`<article class="card battle-ranking-card ${cls(i)}">
    <div class="battle-rank-badge">${medal(i)}<span>${i+1}º</span></div>
    <div class="battle-rank-info">
      <strong>${esc(x.name)}</strong>
      <div class="muted">${esc(x.division)}</div>
    </div>
    <div class="battle-rank-points">${fmtPoints(x.points)}<small>pontos</small></div>
    <div class="card-actions battle-admin-actions">
      <button class="btn small" onclick="editBattleGroup(${x.id})">✏️ Editar</button>
      <button class="btn danger small" onclick="removeBattleGroup(${x.id})">Excluir</button>
    </div>
  </article>`).join(''):`<div class="empty">Nenhum grupo de batalha cadastrado.</div>`;
}
function editBattleGroup(id){
  const x=loadJSON('gow_battle_groups',[]).find(x=>x.id===id); if(!x)return;
  $('bgId').value=x.id;$('bgName').value=x.name;$('bgDivision').value=x.division;$('bgPoints').value=fmtPoints(x.points);$('bgName').focus();toast('Edite qualquer dado do grupo e salve novamente.');
}
function removeBattleGroup(id){saveJSON('gow_battle_groups',loadJSON('gow_battle_groups',[]).filter(x=>x.id!==id));renderBattleGroups();}

function battleEvolution(x){
 const points=Number(x?.points)||0;
 const hist=Array.isArray(x?.pointHistory)?x.pointHistory:[];
 let previous=null;
 if(hist.length>=2) previous=Number(hist[hist.length-2].points)||0;
 else if(x?.previousPoints!==undefined && x?.previousPoints!==null) previous=Number(x.previousPoints)||0;
 const delta=previous===null?0:points-previous;
 const percent=previous>0?(delta/previous)*100:0;
 return {points,previous,delta,percent,hasPrevious:previous!==null};
}
function evolutionLabel(x){
 const e=battleEvolution(x);
 if(!e.hasPrevious) return '—';
 const sign=e.delta>0?'+':e.delta<0?'−':'';
 return `${sign}${fmtPoints(Math.abs(e.delta))} (${e.percent>=0?'+':''}${e.percent.toFixed(2)}%)`;
}
function evolutionClass(x){const e=battleEvolution(x);return e.delta>0?'up':e.delta<0?'down':'same'}
function addBattleManager(e){
 e.preventDefault(); const a=loadJSON('gow_battle_managers',[]); const id=Number($('bmId').value||0);
 const points=parsePoints($('bmPoints').value);
 const item={nick:$('bmNick').value.trim(),points,group:$('bmGroup').value,level:$('bmLevel').value,updated:Date.now()};
 if(!item.nick||!item.group||!item.level){toast('Preencha todos os dados do treinador.');return;}
 const prepareUpdate=(x)=>{
   const oldPoints=Number(x.points)||0;
   const history=Array.isArray(x.pointHistory)?x.pointHistory.slice():[];
   if(!history.length) history.push({at:x.updated||Date.now(),points:oldPoints});
   if(points!==oldPoints) history.push({at:Date.now(),points});
   item.pointHistory=history;
   item.previousPoints=points!==oldPoints?oldPoints:(x.previousPoints??null);
   item.lastPointChange=points!==oldPoints?points-oldPoints:(x.lastPointChange??0);
   item.lastPointChangeAt=points!==oldPoints?Date.now():(x.lastPointChangeAt||null);
   Object.assign(x,item);
 };
 if(id){const x=a.find(x=>x.id===id); if(x)prepareUpdate(x); toast('Todos os dados do treinador foram atualizados!');}
 else {const existing=a.find(x=>x.nick.toLowerCase()===item.nick.toLowerCase()&&x.group===item.group); if(existing){prepareUpdate(existing);toast('Treinador existente atualizado!');}else{item.id=Date.now();item.pointHistory=[{at:item.updated,points}];item.previousPoints=null;item.lastPointChange=0;item.lastPointChangeAt=null;a.push(item);toast('Treinador cadastrado!');}}
 if(!saveJSON('gow_battle_managers',a))return;
 e.target.reset();$('bmId').value='';cancelBattleManagerEdit(false);renderBattleManagers();
}
function renderBattleManagers(){
  const all=loadJSON('gow_battle_managers',[]);
  const render=(group,theme)=>{
    const rows=all.filter(x=>(x.group||'THE GHOSTS OF SPARTA')===group).sort((x,y)=>y.points-x.points);
    return rows.map((x,i)=>{
      const medal=i===0?'🥇':i===1?'🥈':i===2?'🥉':'🏅';
      const cls=i<3?`battle-top-${i+1}`:'battle-standard';
      return `<article class="card battle-manager-card ${theme} ${cls}">
        <div class="battle-manager-badge">${medal}<span>${i+1}º</span></div>
        <div class="battle-manager-info">
          <strong>${esc(x.nick)}</strong>
          <div class="muted">${esc(formatTrainerLevel(x.level))}</div>
          <div class="battle-evolution ${evolutionClass(x)}">📈 Evolução: ${esc(evolutionLabel(x))}</div>
        </div>
        <div class="battle-manager-points">${fmtPoints(x.points)}<small>pontos</small><div class="battle-points-change ${evolutionClass(x)}">${esc(evolutionLabel(x))}</div></div>
        <div class="card-actions battle-admin-actions">
          <button class="btn small" onclick="editBattleManager(${x.id})">✏️ Editar</button>
          <button class="btn danger small" onclick="removeBattleManager(${x.id})">Excluir</button>
        </div>
      </article>`;
    }).join('');
  };
  $('battleManagersListA').innerHTML=render('THE GHOSTS OF SPARTA','red')||`<div class="empty">Nenhum treinador cadastrado neste grupo.</div>`;
  $('battleManagersListB').innerHTML=render('THE GHOSTS OF SPARTA B','blue')||`<div class="empty">Nenhum treinador cadastrado neste grupo.</div>`;
}
function pdfWinAnsi(text){
  const map={'á':0xE1,'à':0xE0,'â':0xE2,'ã':0xE3,'ä':0xE4,'ç':0xE7,'é':0xE9,'ê':0xEA,'ë':0xEB,'í':0xED,'ï':0xEF,'ó':0xF3,'ô':0xF4,'õ':0xF5,'ö':0xF6,'ú':0xFA,'ü':0xFC,'Á':0xC1,'À':0xC0,'Â':0xC2,'Ã':0xC3,'Ä':0xC4,'Ç':0xC7,'É':0xC9,'Ê':0xCA,'Ë':0xCB,'Í':0xCD,'Ï':0xCF,'Ó':0xD3,'Ô':0xD4,'Õ':0xD5,'Ö':0xD6,'Ú':0xDA,'Ü':0xDC,'º':0xBA,'ª':0xAA,'–':0x96,'—':0x97,'•':0x95};
  let out=''; for(const ch of String(text??'')){const c=map[ch]??ch.charCodeAt(0); out+=String.fromCharCode(c<=255?c:0x3F);} return out.replace(/([\\()])/g,'\\$1').replace(/\r?\n/g,' ');
}
