function b64Bytes(dataUrl){const b64=String(dataUrl||'').split(',')[1]||'';if(!b64)return new Uint8Array();const bin=atob(b64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return u}
