function getTitleRankings(){
  const history=getHistory();
  const count=cat=>{const m={};history.filter(x=>x.cat===cat).forEach(x=>m[x.champion]=(m[x.champion]||0)+1);return Object.entries(m).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));};
  const league=count('Liga'),cup=count('Copa'),tour=count('Torneio');
  const all={};[...league,...cup,...tour].forEach(([n,v])=>all[n]=(all[n]||0)+v);
  return {overall:Object.entries(all).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])),league,cup,tour};
}
function pdfSafeText(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/π/g,'p').replace(/[\\()\r\n]/g,' ').replace(/[^\x20-\x7E]/g,'?');}
