function makeSimplePDF(pages){
  const W=595,H=842,enc=s=>latin1Bytes(s),objs=[];const addObj=x=>{objs.push(x);return objs.length};
  const catalog=addObj(''),pagesObj=addObj('');const pageRefs=[];const contentRefs=[];const font=addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');const bold=addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
  const specs=pages.map(p=>typeof p==='string'?{content:p,images:[]}:p);
  specs.forEach(spec=>{
    const images=spec.images||[], imageRefs=[];
    images.forEach(img=>{
      const data=b64Bytes(img.dataUrl);const ref=addObj(`<< /Type /XObject /Subtype /Image /Width ${img.pixelWidth||1536} /Height ${img.pixelHeight||1536} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${data.length} >>\nstream\n${bytesToLatin1(data)}\nendstream`);imageRefs.push({name:img.name||('Im'+ref),ref});
    });
    // Lineup templates are backgrounds: draw them BEFORE the saved trainer text.
    // Other PDFs retain their original vector-first order for visible header logos.
    const imageCommands=images.map((img,i)=>`\nq ${img.w||48} 0 0 ${img.h||48} ${img.x||0} ${img.y||0} cm /${imageRefs[i].name} Do Q`).join('');
    let content=spec.imageBehind?(imageCommands+'\n'+(spec.content||'')):('\n'+(spec.content||'')+imageCommands);
    const page=addObj('');const cont=addObj('');pageRefs.push(page);contentRefs.push(cont);
    const xobj=imageRefs.length?` /XObject << ${imageRefs.map(x=>`/${x.name} ${x.ref} 0 R`).join(' ')} >>`:'';
    const bytes=enc(content);objs[cont-1]=`<< /Length ${bytes.length} >>\nstream\n${content}\nendstream`;
    objs[page-1]=`<< /Type /Page /Parent ${pagesObj} 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 ${font} 0 R /F2 ${bold} 0 R >>${xobj} >> /Contents ${cont} 0 R >>`;
  });
  objs[catalog-1]=`<< /Type /Catalog /Pages ${pagesObj} 0 R >>`;objs[pagesObj-1]=`<< /Type /Pages /Kids [${pageRefs.map(n=>n+' 0 R').join(' ')}] /Count ${pageRefs.length} >>`;
  const header=enc('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n'),chunks=[header],offsets=[0];let pos=header.length;
  for(let i=0;i<objs.length;i++){const b=enc(`${i+1} 0 obj\n${objs[i]}\nendobj\n`);offsets.push(pos);chunks.push(b);pos+=b.length;}
  let xref=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;for(let i=1;i<offsets.length;i++)xref+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';xref+=`trailer\n<< /Size ${objs.length+1} /Root ${catalog} 0 R >>\nstartxref\n${pos}\n%%EOF`;chunks.push(enc(xref));return new Blob(chunks,{type:'application/pdf'});
}
