function rankingPage(section,pageNo,totalPages,offset=0){
  // Clean vector-only PDF: no background JPEGs, watermarks, or overlay rectangles.
  const W=595,H=842,cmd=[],logoW=480,logoH=449;
  const safe=v=>pdfSafeText(v).replace(/\?/g,'');
  const rect=(x,y,w,h,color)=>cmd.push(`${color} rg ${x} ${H-y-h} ${w} ${h} re f`);
  const line=(x1,y1,x2,y2,color='0.84 0.87 0.91',width=.65)=>cmd.push(`${color} RG ${width} w ${x1} ${H-y1} m ${x2} ${H-y2} l S`);
  const txt=(x,y,size,value,bold=false,color='0.04 0.12 0.24')=>cmd.push(`${color} rg BT /F${bold?2:1} ${size} Tf ${x} ${H-y} Td (${safe(value)}) Tj ET`);
  const titles=['RANKING GERAL DE CAMPEOES','RANKING DAS LIGAS','RANKING DAS COPAS','RANKING DOS TORNEIOS'];
  rect(0,0,W,H,'1 1 1');
  rect(25,24,545,91,'0.035 0.10 0.20');
  rect(25,24,7,91,'0.87 0.09 0.13');
  txt(150,58,19,'THE GHOSTS OF SPARTA',true,'1 1 1');
  txt(150,85,11,'RANKINGS OFICIAIS - CAMPEOES',true,'1 0.83 0.24');
  txt(500,99,9,`PAG. ${pageNo}/${totalPages}`,true,'1 1 1');
  txt(32,153,18,section.title||titles[pageNo-1]||'RANKING',true);
  txt(32,174,10,'Classificacao atualizada automaticamente com os titulos cadastrados.');
  rect(25,194,545,35,'0.035 0.10 0.20');
  txt(39,217,11,'POS.',true,'1 1 1');
  txt(111,217,11,'TREINADOR',true,'1 1 1');
  txt(493,217,11,'TITULOS',true,'1 1 1');
  const rows=section.rows||[], rowH=25, maxRows=21;
  rows.slice(offset,offset+maxRows).forEach((r,i)=>{
    const y=229+i*rowH;
    if(i%2===1)rect(25,y,545,rowH,'0.90 0.95 0.98');
    const name=String(r[0]??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7e]/g,'').trim();
    txt(43,y+17,10,String(offset+i+1),true,'0.85 0.07 0.12');
    txt(111,y+17,10,name.length>57?name.slice(0,54)+'...':name,true);
    txt(511,y+17,10,String(r[1]??0),true);
    line(25,y+rowH,570,y+rowH);
  });
  line(94,194,94,754);line(477,194,477,754);
  line(25,754,570,754,'0.85 0.07 0.12',1.5);
  rect(25,773,545,43,'0.035 0.10 0.20');
  txt(123,800,10,'THE GHOSTS OF SPARTA  -  RANKINGS OFICIAIS',true,'1 1 1');
  // Two red outlines: external page frame and internal content frame.
  const frame=(x,y,w,h,lw)=>{cmd.push(`0.87 0.06 0.10 RG ${lw} w ${x} ${H-y} ${w} ${-h} re S`);};
  frame(9,9,577,824,3);
  frame(20,19,555,803,1.3);
  // Exact supplied crest, composited only on the header navy, no ornamental background.
  return {content:cmd.join('\n'),images:[{name:'OfficialCrest',dataUrl:SPARTA_OFFICIAL_CREST_JPG,pixelWidth:logoW,pixelHeight:logoH,x:42,y:H-105,w:76,h:76}]};
}
function buildTitlesRankingPDF(){
  const d=getTitleRankings();
  const sections=[
    {title:'RANKING GERAL DE CAMPEOES',rows:d.overall},
    {title:'RANKING DAS LIGAS',rows:d.league},
    {title:'RANKING DAS COPAS',rows:d.cup},
    {title:'RANKING DOS TORNEIOS',rows:d.tour}
  ];
  const pages=[];
  sections.forEach((sec,i)=>{
    const n=Math.max(1,Math.ceil(sec.rows.length/21));
    for(let part=0;part<n;part++)pages.push(rankingPage({...sec,title:n>1?sec.title+' - CONTINUACAO '+(part+1):sec.title},i+1,4,part*21));
  });
  return makeSimplePDF(pages);
}
function downloadTitlesRankingPDF(){const blob=buildTitlesRankingPDF();downloadFile(new File([blob],'GOW_Rankings_Campeoes.pdf',{type:'application/pdf'}));toast('PDF dos rankings baixado!');}
